bash:
python3 - <<'EOF'
p='apps/demo/src/styles/demo.css'; s=open(p).read()
old=s.split('\n')[315]
assert old.startswith('@media (prefers-color-scheme: light) { :root:not([data-theme="dark"]) {'), old[:80]
vals=old[old.index('{ --role')+2:old.rindex('} }')].strip()
new=old+'\n:root[data-theme="light"] { '+vals+' }   /* the shell\'s Light choice (D9) wins on a dark device too */'
s=s.replace(old,new,1); open(p,'w').write(s); print(new[-200:])
p='tests/browser/demo-viewas.test.mjs'; s=open(p).read()
anchor="  // ---- the screenshots for the founder at 390 and 1440 (evidence only)\n"
add='''  // ---- the role colours follow the theme the person chooses, not only the device's (D9). Added with the tokens v2 integration: the light
  // steps were applied for a light device but not for the shell's Light choice on a dark device, which left dark-tuned colours on light cards.
  { const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, colorScheme: 'dark' }); const page = await ctx.newPage();
    await page.goto(base + '#/investor'); await page.waitForSelector('[data-testid=viewas-open]');
    const roleOf = () => page.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue('--role-designer').trim());
    const sys = await roleOf(); await page.click('[data-theme-opt=light]'); await page.waitForTimeout(100); const chosenLight = await roleOf();
    await page.click('[data-theme-opt=dark]'); await page.waitForTimeout(100); const chosenDark = await roleOf();
    const c2 = await browser.newContext({ viewport: { width: 1440, height: 900 }, colorScheme: 'light' }); const p2 = await c2.newPage(); await p2.goto(base + '#/investor'); await p2.waitForSelector('[data-testid=viewas-open]');
    const sysLight = await p2.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue('--role-designer').trim());
    ok('VA-theme-16', 'the role colours take their light steps when Light is chosen by hand on a dark device, and their dark steps when Dark is chosen; the same light step as a light device', sys === '#d55753' && chosenLight === '#a51e24' && chosenDark === '#d55753' && sysLight === '#a51e24', JSON.stringify({ sys, chosenLight, chosenDark, sysLight }));
    await ctx.close(); await c2.close(); }
'''
assert anchor in s; s=s.replace(anchor, add+anchor,1); open(p,'w').write(s); print('test added')
EOF
cd apps/demo && node build.mjs > /dev/null 2>&1; echo build $?; cd ../.. && for sc in light dark; do PW_COLOR_SCHEME=$sc flock /tmp/empathia-test.lock node --import ./tests/browser/color-scheme.mjs tests/browser/demo-viewas.test.mjs 2>&1 | grep -E "^FAIL|VA-theme|passed"; done
